import Foundation

// MARK: - Monthly-updated static data (station catalog, express data, bus stops)
//
// The app ships a copy (Resources/, generated by the Python scripts in tools/). After the 1st of each month the app downloads static GTFS from MTA,
// regenerates files in the same format with SubwayStaticBuilder / BusStaticBuilder, and saves them in the shared folder (SharedFolder);
// when the main app and widget read them, the downloaded copy is used only if it's newer than the bundled one.

public enum StaticData {
    /// Folder for downloaded files (set to a folder in the shared folder when the app and widget start). nil means use only the bundled copy.
    public static var directory: URL? {
        get { box.value }
        set { box.value = newValue }
    }
    private static let box = DirectoryBox()

    public static let stationsFile = "subway_stations.json"
    public static let expressFile = "express_stops.json"
    public static let busStopsFile = "bus_stops.json"

    /// Write into `directory` (write a temp file then replace, so readers never see a half-written file). Creates the folder first if missing.
    public static func save(_ data: Data, as name: String) throws {
        guard let dir = directory else { throw CocoaError(.fileNoSuchFile) }
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        try data.write(to: dir.appendingPathComponent(name), options: .atomic)
    }

    /// Contents of the downloaded file; nil if none.
    static func downloaded(_ name: String) -> Data? {
        guard let dir = directory else { return nil }
        return try? Data(contentsOf: dir.appendingPathComponent(name))
    }

    /// GTFS data versions start with a date ("20260826-X-long-term-…", "20260813"): later dates are newer; equal dates compare as strings.
    public static func isNewer(_ version: String, than other: String) -> Bool {
        let a = leadingDate(version), b = leadingDate(other)
        if a != b { return (a ?? -1) > (b ?? -1) }
        return Py.less(other, version)
    }

    /// The leading 8-digit date (yyyymmdd); nil if it doesn't start with digits.
    static func leadingDate(_ version: String) -> Int? {
        let head = version.utf8.prefix(8)
        guard head.count == 8, head.allSatisfy({ (0x30...0x39).contains($0) }) else { return nil }
        return Int(String(decoding: head, as: UTF8.self))
    }

    /// The newly generated station catalog looks sane (guards against download or parse errors, regardless of content changes):
    /// station count within 10% of the old one, and at least 95% of the old stations still there (by id, or by name nearby with a
    /// new id: see DataJudgement)
    public static func plausible(new: StationCatalog, old: StationCatalog) -> Bool {
        judge(new: DataListing(new), old: DataListing(old), limits: .subwayStations)
    }

    /// Bus stops: stop count within 25%, and at least 70% of the old stops still there
    public static func plausible(new: BusCatalog, old: BusCatalog) -> Bool {
        judge(new: DataListing(new), old: DataListing(old), limits: .cityBusStops)
    }

    private static func judge(new: DataListing, old: DataListing, limits: DataJudgement.Limits) -> Bool {
        if case .tooDifferent = DataJudgement.of(old: old, new: new, limits: limits) { return false }
        return true
    }

    /// Whether a newly generated list takes the current one's place (DataUpdateGate, logged under `key`). The bundled copy
    /// in use is held against too: it is the data in use until one was downloaded
    static func passes(key: String, new: DataListing, current: DataListing?, limits: DataJudgement.Limits) -> Bool {
        DataUpdateGate.check(key: key, old: current, new: new, limits: limits)
    }

    // MARK: Saving after the monthly check

    /// What happened to the newly generated station list
    public enum SaveResult: Equatable, Sendable {
        /// Replaced with the new one
        case saved
        /// Same as the one in use
        case unchanged
        /// Not newer than the bundled one: delete the previous download (fall back to the bundled one)
        case notNewer
        /// Looks wrong (many stations missing, etc.), not replaced
        case implausible
        /// Its version doesn't start with a date, so it can't be told whether it's newer: nothing saved and nothing deleted,
        /// the one in use stays (the next monthly check tries again)
        case unknownVersion
    }

    /// Save the station catalog and express data regenerated by the monthly check (express data first, then the catalog).
    /// Replace only if newer than the bundled one, different from the one in use, and sane-looking. A version without a date
    /// changes nothing (see SaveResult.unknownVersion).
    public static func saveSubway(stations: Data, express: Data) throws -> SaveResult {
        let fresh = try StationCatalog.decode(stations)
        _ = try ExpressStops.decode(express)   // save only if it can be read
        guard leadingDate(fresh.feedVersion) != nil else { return .unknownVersion }
        guard isNewer(fresh.feedVersion, than: bundledStationsVersion) else {
            remove(stationsFile)
            remove(expressFile)
            return .notNewer
        }
        if downloaded(stationsFile) == stations, downloaded(expressFile) == express { return .unchanged }
        if !passes(key: DataChangeLog.subwayKey, new: DataListing(fresh), current: (try? StationCatalog.loadCurrent()).map(DataListing.init),
                   limits: .subwayStations) { return .implausible }
        // The two files must match: if saving the catalog fails, revert the express data so old and new aren't mixed
        let oldExpress = downloaded(expressFile)
        try save(express, as: expressFile)
        do {
            try save(stations, as: stationsFile)
        } catch {
            if let oldExpress { try? save(oldExpress, as: expressFile) } else { remove(expressFile) }
            throw error
        }
        return .saved
    }

    /// Save the bus stop catalog regenerated by the monthly check (same rules as saveSubway).
    public static func saveBus(stops: Data) throws -> SaveResult {
        let fresh = try BusCatalog.decode(stops)
        guard leadingDate(fresh.feedVersion) != nil else { return .unknownVersion }
        guard isNewer(fresh.feedVersion, than: bundledBusVersion) else {
            remove(busStopsFile)
            return .notNewer
        }
        if downloaded(busStopsFile) == stops { return .unchanged }
        if !passes(key: DataChangeLog.cityBusKey, new: DataListing(fresh), current: (try? BusCatalog.loadCurrent()).map(DataListing.init),
                   limits: .cityBusStops) { return .implausible }
        try save(stops, as: busStopsFile)
        return .saved
    }

    static func remove(_ name: String) {
        guard let dir = directory else { return }
        try? FileManager.default.removeItem(at: dir.appendingPathComponent(name))
    }

    // MARK: Bundled version

    /// Data version of the bundled file (read only once).
    static let bundledStationsVersion = bundledVersion("subway_stations")
    static let bundledBusVersion = bundledVersion("bus_stops")

    private struct VersionOnly: Decodable { var feedVersion: String? }

    private static func bundledVersion(_ resource: String) -> String {
        guard let data = bundledData(resource) else { return "" }
        return (try? JSONDecoder().decode(VersionOnly.self, from: data))?.feedVersion ?? ""
    }

    /// The bundled file (Resources/<resource>.json)
    static func bundledData(_ resource: String) -> Data? {
        guard let url = Bundle.module.url(forResource: resource, withExtension: "json") else { return nil }
        return try? Data(contentsOf: url)
    }
}

/// Storage for `StaticData.directory` (set at app launch, then read from any thread).
private final class DirectoryBox: @unchecked Sendable {
    private let lock = NSLock()
    private var url: URL?

    var value: URL? {
        get { lock.lock(); defer { lock.unlock() }; return url }
        set { lock.lock(); url = newValue; lock.unlock() }
    }
}

extension StationCatalog {
    /// Station catalog in use: the downloaded one if readable and newer than the bundled one, otherwise the bundled one.
    public static func loadCurrent() throws -> StationCatalog {
        try downloadedCopy() ?? loadBundled()
    }

    /// The downloaded copy (readable and newer than the bundled one); otherwise nil.
    static func downloadedCopy() -> StationCatalog? {
        guard let data = StaticData.downloaded(StaticData.stationsFile), let copy = try? decode(data),
              StaticData.isNewer(copy.feedVersion, than: StaticData.bundledStationsVersion) else { return nil }
        return copy
    }
}

extension ExpressStops {
    /// express_stops.json has no version and updates with the station catalog: the downloaded copy is used only while the downloaded catalog is in use (if readable).
    public static func loadCurrent() throws -> ExpressStops {
        if StationCatalog.downloadedCopy() != nil, let data = StaticData.downloaded(StaticData.expressFile),
           let copy = try? decode(data) {
            return copy
        }
        return try loadBundled()
    }

    /// Express data matching this station catalog: the downloaded express data if the catalog is the downloaded one (newer than bundled), otherwise the bundled one.
    /// Use this when the catalog is already loaded, to avoid reading it again.
    public static func loadCurrent(for catalog: StationCatalog) throws -> ExpressStops {
        if StaticData.isNewer(catalog.feedVersion, than: StaticData.bundledStationsVersion),
           let data = StaticData.downloaded(StaticData.expressFile), let copy = try? decode(data) {
            return copy
        }
        return try loadBundled()
    }
}

extension BusCatalog {
    /// Bus stop catalog in use: the downloaded one if readable and newer than the bundled one, otherwise the bundled one.
    public static func loadCurrent() throws -> BusCatalog {
        if let data = StaticData.downloaded(StaticData.busStopsFile), let copy = try? decode(data),
           StaticData.isNewer(copy.feedVersion, than: StaticData.bundledBusVersion) {
            return copy
        }
        return try loadBundled()
    }
}

// MARK: - Doing it the Python way
//
// Generated files must be byte-identical to the Python scripts in tools/, so these small helpers handle strings, numbers and JSON by Python's rules.

enum Py {
    /// Python string comparison: by Unicode code point (same as UTF-8 byte order).
    static func less(_ a: String, _ b: String) -> Bool {
        a.utf8.lexicographicallyPrecedes(b.utf8)
    }

    /// str.isspace(): Unicode whitespace, plus 0x1C–0x1F.
    static func isSpace(_ u: Unicode.Scalar) -> Bool {
        u.properties.isWhitespace || (0x1C...0x1F).contains(u.value)
    }

    /// str.strip()
    static func strip(_ s: String) -> String {
        let u = s.unicodeScalars
        guard let first = u.firstIndex(where: { !isSpace($0) }), let last = u.lastIndex(where: { !isSpace($0) }) else {
            return ""
        }
        return string(u[first...last])
    }

    static func string<S: Sequence>(_ scalars: S) -> String where S.Element == Unicode.Scalar {
        var v = String.UnicodeScalarView()
        v.append(contentsOf: scalars)
        return String(v)
    }

    /// float(): whitespace allowed on both sides (bus stops.txt coordinates have leading spaces).
    static func float(_ s: String) -> Double? { Double(strip(s)) }

    /// int()
    static func int(_ s: String) -> Int? { Int(strip(s)) }

    /// \d in regex: Unicode decimal digits.
    static func isDigit(_ u: Unicode.Scalar) -> Bool { u.properties.numericType == .decimal }

    /// Under re.IGNORECASE, whether ASCII character p in the pattern matches u (Python also lets U+017F match s, U+0131 and U+0130 match i, U+212A match k).
    static func matchesIgnoringCase(_ u: Unicode.Scalar, _ p: Unicode.Scalar) -> Bool {
        if u == p { return true }
        guard p.properties.isAlphabetic, p.isASCII else { return false }
        let upper = Unicode.Scalar(UInt8(ascii: p) & 0xDF)
        if u.isASCII { return Unicode.Scalar(UInt8(ascii: u) & 0xDF) == upper && u.properties.isAlphabetic }
        switch (upper, u.value) {
        case ("S", 0x017F), ("I", 0x0131), ("I", 0x0130), ("K", 0x212A): return true
        default: return false
        }
    }

    /// Whether s at `at` starts with pattern (case-insensitive).
    static func hasPrefixIgnoringCase(_ s: [Unicode.Scalar], at i: Int, _ pattern: String) -> Bool {
        var k = i
        for p in pattern.unicodeScalars {
            guard k < s.count, matchesIgnoringCase(s[k], p) else { return false }
            k += 1
        }
        return true
    }

    /// needle in hay (substring search by code point)
    static func contains(_ hay: String, _ needle: String) -> Bool {
        let h = Array(hay.utf8), n = Array(needle.utf8)
        guard !n.isEmpty else { return true }
        guard h.count >= n.count else { return false }
        for i in 0...(h.count - n.count) where h[i..<(i + n.count)].elementsEqual(n) { return true }
        return false
    }

    /// round(x, digits): rounds by x's exact binary value, ties to even
    /// (not quite the same as (x * 10^digits).rounded() / 10^digits, e.g. round(40.0078125, 6) = 40.007812).
    /// Only for decimals like coordinates; returned unchanged when |x| · 10^digits ≥ 2^52.
    static func round(_ x: Double, _ digits: Int) -> Double {
        var scale = 1.0
        for _ in 0..<digits { scale *= 10 }
        let y = x * scale
        guard x.isFinite, y.magnitude < 0x1p52 else { return x }
        // y has rounding error: use fused multiply-add (one rounding) to tell exactly which two integers x·scale lies between and compare with the midpoint
        var q = y.rounded(.down)
        if (-q).addingProduct(x, scale) < 0 {
            q -= 1
        } else if (-(q + 1)).addingProduct(x, scale) >= 0 {
            q += 1
        }
        let d = (-(q + 0.5)).addingProduct(x, scale)
        if d > 0 || (d == 0 && q.truncatingRemainder(dividingBy: 2) != 0) { q += 1 }
        let r = q / scale
        return r == 0 ? (x.sign == .minus ? -0.0 : 0.0) : r
    }

    /// repr(float): the shortest round-tripping form (same digits as Swift's description),
    /// scientific notation when the exponent is below -4 or at least 16; integers get ".0".
    static func repr(_ x: Double) -> String {
        if x.isNaN { return "NaN" }
        if x.isInfinite { return x < 0 ? "-Infinity" : "Infinity" }
        var text = x.magnitude.description
        var exponent = 0
        if let e = text.firstIndex(where: { $0 == "e" || $0 == "E" }) {
            exponent = Int(text[text.index(after: e)...]) ?? 0
            text = String(text[..<e])
        }
        let parts = text.split(separator: ".", omittingEmptySubsequences: false)
        var digits = Array(parts[0].utf8) + (parts.count > 1 ? Array(parts[1].utf8) : [])
        // The decimal point comes after this many digits (value = 0.digits × 10^point)
        var point = parts[0].utf8.count + exponent
        let zero = UInt8(ascii: "0")
        while digits.count > 1, digits.first == zero { digits.removeFirst(); point -= 1 }
        while digits.count > 1, digits.last == zero { digits.removeLast() }
        let sign = x.sign == .minus ? "-" : ""
        if digits == [zero] { return sign + "0.0" }
        let d = String(decoding: digits, as: UTF8.self)
        if point > -4 && point <= 16 {
            if point <= 0 { return sign + "0." + String(repeating: "0", count: -point) + d }
            if point >= digits.count { return sign + d + String(repeating: "0", count: point - digits.count) + ".0" }
            return sign + String(d.prefix(point)) + "." + String(d.dropFirst(point))
        }
        let e = point - 1
        let mantissa = digits.count > 1 ? String(d.prefix(1)) + "." + String(d.dropFirst()) : d
        return sign + mantissa + "e" + (e < 0 ? "-" : "+") + (abs(e) < 10 ? "0" : "") + String(abs(e))
    }
}

/// Writes JSON in the format of Python's json.dump(..., separators=(",", ":")).
struct PyJSON {
    private(set) var text = ""
    /// ensure_ascii=True (Python's default): non-ASCII characters are written as \uXXXX
    let asciiOnly: Bool

    init(asciiOnly: Bool = false) {
        self.asciiOnly = asciiOnly
    }

    var data: Data { Data(text.utf8) }

    mutating func raw(_ s: String) { text += s }

    mutating func string(_ s: String) {
        text += "\""
        for u in s.unicodeScalars {
            switch u {
            case "\"": text += "\\\""
            case "\\": text += "\\\\"
            case "\n": text += "\\n"
            case "\r": text += "\\r"
            case "\t": text += "\\t"
            case "\u{08}": text += "\\b"
            case "\u{0C}": text += "\\f"
            default:
                if u.value < 0x20 || (asciiOnly && u.value > 0x7E) {
                    if u.value > 0xFFFF {
                        let v = u.value - 0x10000
                        text += Self.hex(0xD800 | (v >> 10)) + Self.hex(0xDC00 | (v & 0x3FF))
                    } else {
                        text += Self.hex(u.value)
                    }
                } else {
                    text.unicodeScalars.append(u)
                }
            }
        }
        text += "\""
    }

    /// String or null
    mutating func string(_ s: String?) {
        if let s { string(s) } else { raw("null") }
    }

    mutating func number(_ x: Double) { text += Py.repr(x) }

    mutating func bool(_ b: Bool) { text += b ? "true" : "false" }

    private static func hex(_ v: UInt32) -> String {
        let h = String(v, radix: 16)
        return "\\u" + String(repeating: "0", count: max(0, 4 - h.count)) + h
    }
}

/// Python's Counter: counts occurrences, keeping first-seen order.
struct Tally<Key: Equatable> {
    private(set) var keys: [Key] = []
    private(set) var counts: [Int] = []

    mutating func add(_ key: Key) {
        if let i = keys.firstIndex(of: key) { counts[i] += 1 } else { keys.append(key); counts.append(1) }
    }

    /// The most common; ties go to the first seen (same as Counter.most_common(1)). nil if empty.
    var mostCommon: Key? {
        var best = -1, bestCount = 0
        for (i, c) in counts.enumerated() where c > bestCount { best = i; bestCount = c }
        return best >= 0 ? keys[best] : nil
    }
}
